// Probe — shared case builders for the playtest of "the ball passes through
// bricks". Each case builds a pure state (ball + bricks, no DOM) plus the
// expected post-collision values. The same cases are run against two targets:
//   1. the naive fix (naiveResolve below)  → must FAIL
//   2. the real resolveBricks (from neon.js) → must FAIL today (missing),
//      then PASS once implemented.
//
// All numbers are computed from the constants of game/neon.js:
//   BRICK_H 20, BALL_R 7 (diameter 14), BRICK_GAP 8,
//   grid origin (4, 48), pitch 80 x 28.
//   ballSpeed(L) = 260 + 90*(L-1); dt capped at 0.05 s.

import { collides, makeBricks } from '../../game/neon.js';

// ---------------------------------------------------------------------------
// The NAIVE FIX — the obvious first attempt a developer writes to make the
// ball "bounce off bricks": check overlap at the final position only, kill the
// brick, flip vy, never reposition, no seam guard, no sweep, no corner rule.
// ---------------------------------------------------------------------------
export function naiveResolve(state) {
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.ball.vy = -state.ball.vy; // always flip vy — wrong axis on side hits
      // no push-out: the ball stays inside the brick
    }
  }
}

// A brick grid; helper to grab one brick by its top-left corner.
export function brickAt(state, x, y) {
  return state.bricks.find((b) => b.x === x && b.y === y);
}

// --- D1: side hit — the ball hits the RIGHT face of a brick, moving LEFT.
// The bounce must flip vx (not vy) and push the ball out to the right.
export function d1Case() {
  const state = { bricks: makeBricks(1), ball: { x: 80, y: 60, px: 80, py: 60, r: 7, vx: -260, vy: 0 } };
  const brick = brickAt(state, 4, 48);
  return { state, brick, label: 'D1 side hit' };
}

// --- D2: tunneling — a full 50 ms step at level 6 (35.5 px) jumps the ball
// from below a brick to above it without ever overlapping it. A bounce must
// still happen (swept / sub-step detection).
export function d2Case() {
  const speed = 260 + 5 * 90; // ballSpeed(6) = 710 — first level where step > BRICK_H + 2*BALL_R = 34
  const dt = 0.05; // clamped max step
  const state = {
    bricks: makeBricks(6),
    ball: { x: 360, y: 188, px: 360, py: 188, r: 7, vx: 0, vy: -speed },
  };
  state.ball.y += state.ball.vy * dt; // 152.5 — above the brick, no overlap at either end
  const brick = brickAt(state, 324, 160); // row 4, col 4
  return { state, brick, label: 'D2 tunneling' };
}

// --- D3: seam — the ball climbs the vertical seam between two columns and
// overlaps BOTH row-1 bricks at once. Exactly one vy flip must happen and both
// bricks must die (a per-brick loop would flip vy twice and cancel out).
export function d3Case() {
  const speed = 710;
  const dt = 0.05;
  const state = {
    bricks: makeBricks(6),
    ball: { x: 80, y: 110, px: 80, py: 110, r: 7, vx: 0, vy: -speed },
  };
  state.ball.y += state.ball.vy * dt; // 74.5
  const b1 = brickAt(state, 4, 76); // row 1, col 0
  const b2 = brickAt(state, 84, 76); // row 1, col 1
  return { state, b1, b2, label: 'D3 seam double flip' };
}

// --- D4: corner — equal penetration on both axes (exactly on the corner).
// Both vx and vy must flip.
export function d4Case() {
  const state = { bricks: makeBricks(1), ball: { x: 6, y: 50, px: 6, py: 50, r: 7, vx: -260, vy: -260 } };
  const brick = brickAt(state, 4, 48);
  return { state, brick, label: 'D4 corner' };
}

// --- D5: push-out — the ball hits the bottom face of a brick; after the
// bounce it must sit OUTSIDE the brick (y = brick.y + brick.h + r), not stay
// overlapping it (else it re-collides and re-flips next frame: "sticking").
export function d5Case() {
  const state = { bricks: makeBricks(1), ball: { x: 40, y: 70, px: 40, py: 70, r: 7, vx: 0, vy: -260 } };
  const brick = brickAt(state, 4, 48);
  return { state, brick, label: 'D5 push-out' };
}

export const allCases = [d1Case, d2Case, d3Case, d4Case, d5Case];

// Probe run #2 — each case asserted against the NAIVE fix. Every test must
// FAIL: the naive fix flips the wrong axis, misses the sweep, cancels the
// double flip at seams, drops the corner, and forgets the push-out.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { naiveResolve, allCases, d1Case, d2Case, d3Case, d4Case, d5Case } from './cases.js';

function run(caseFn) {
  const c = caseFn();
  naiveResolve(c.state);
  return c;
}

test('D1 naive: side hit flips vx, ball pushed out right', () => {
  const c = run(d1Case);
  assert.equal(c.brick.alive, false);
  assert.equal(c.state.ball.vx, 260, 'vx must flip to the right on a right-face hit');
  assert.equal(c.state.ball.vy, 0, 'vy unchanged on a side hit');
  assert.equal(c.state.ball.x, 83, 'ball pushed out of the brick (76 + 7)');
});

test('D2 naive: a 35.5 px step at level 6 still bounces', () => {
  const c = run(d2Case);
  assert.equal(c.brick.alive, false, 'brick must be destroyed even if never overlapped at the end position');
  assert.equal(c.state.ball.vy, 710, 'vy flipped back down');
  assert.ok(c.state.ball.y >= 187, 'ball ends below the brick, not above it');
});

test('D3 naive: seam overlap flips vy exactly once, both bricks die', () => {
  const c = run(d3Case);
  assert.equal(c.b1.alive, false, 'left seam brick dies');
  assert.equal(c.b2.alive, false, 'right seam brick dies');
  assert.equal(c.state.ball.vy, 710, 'vy flipped exactly once (two flips would cancel)');
  assert.equal(c.state.ball.vx, 0, 'vx untouched');
});

test('D4 naive: corner hit flips both vx and vy', () => {
  const c = run(d4Case);
  assert.equal(c.state.ball.vx, 260, 'corner flips vx too');
  assert.equal(c.state.ball.vy, 260, 'corner flips vy');
});

test('D5 naive: after resolution the ball is outside the brick', () => {
  const c = run(d5Case);
  assert.equal(c.state.ball.y, 75, 'ball pushed out below the brick (68 + 7)');
  assert.equal(c.state.ball.vy, 260, 'vy flipped up');
});

// Probe run #1 — the five cases against the REAL `resolveBricks`.
// Today the function does not exist in game/neon.js (the brick bounce is
// missing entirely, bug reported by the player): the module import below
// fails, which is the red run. Once implemented, this file must go green.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { resolveBricks } from '../../game/neon.js';
import { d1Case, d2Case, d3Case, d4Case, d5Case } from './cases.js';

function run(caseFn) {
  const c = caseFn();
  resolveBricks(c.state);
  return c;
}

test('D1: side hit flips vx, ball pushed out right', () => {
  const c = run(d1Case);
  assert.equal(c.brick.alive, false);
  assert.equal(c.state.ball.vx, 260, 'vx must flip to the right on a right-face hit');
  assert.equal(c.state.ball.vy, 0, 'vy unchanged on a side hit');
  assert.equal(c.state.ball.x, 83, 'ball pushed out of the brick (76 + 7)');
});

test('D2: a 35.5 px step at level 6 still bounces', () => {
  const c = run(d2Case);
  assert.equal(c.brick.alive, false, 'brick must be destroyed even if never overlapped at the end position');
  assert.equal(c.state.ball.vy, 710, 'vy flipped back down');
  assert.ok(c.state.ball.y >= 187, 'ball ends below the brick, not above it');
});

test('D3: seam overlap flips vy exactly once, both bricks die', () => {
  const c = run(d3Case);
  assert.equal(c.b1.alive, false, 'left seam brick dies');
  assert.equal(c.b2.alive, false, 'right seam brick dies');
  assert.equal(c.state.ball.vy, 710, 'vy flipped exactly once (two flips would cancel)');
  assert.equal(c.state.ball.vx, 0, 'vx untouched');
});

test('D4: corner hit flips both vx and vy', () => {
  const c = run(d4Case);
  assert.equal(c.state.ball.vx, 260, 'corner flips vx too');
  assert.equal(c.state.ball.vy, 260, 'corner flips vy');
});

test('D5: after resolution the ball is outside the brick', () => {
  const c = run(d5Case);
  assert.equal(c.state.ball.y, 75, 'ball pushed out below the brick (68 + 7)');
  assert.equal(c.state.ball.vy, 260, 'vy flipped up');
});

