// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick bounce resolution lives in the pure
// `resolveBricks()` (called by `frame()` after this): here we only record the
// position before moving, so the resolver can sweep the travelled path and
// catch fast steps that would otherwise jump over a brick (see D2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.px = ball.x;
  ball.py = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

