// Main render loop. Brick physics is handled by the pure `resolveBricks()`
// (bounce + destruction); this loop only scores the destroyed bricks and
// draws the field.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Brick physics: pure bounce resolution (per-face, swept, seam-safe).
