edits.newText:
// --- D3: seam — the ball climbs the seam between two columns from below the
// grid and first touches the bottom faces of the two side-by-side row-4
// bricks at the same instant. Exactly one vy flip must happen and both bricks
// must die (a per-brick loop would flip vy twice and cancel out).
export function d3Case() {
  const speed = 710;
  const dt = 0.05;
  const state = {
    bricks: makeBricks(6),
    ball: { x: 80, y: 188, px: 80, py: 188, r: 7, vx: 0, vy: -speed },
  };
  state.ball.y += state.ball.vy * dt; // 152.5
  const b1 = brickAt(state, 4, 160); // row 4, col 0
  const b2 = brickAt(state, 84, 160); // row 4, col 1
  return { state, b1, b2, label: 'D3 seam double flip' };
}

edits.oldText:
// --- D3: seam — the ball climbs the vertical seam between two columns and
// overlaps BOTH row-1 bricks at once. Exactly one vy flip must happen and both
// bricks must die (a per-brick loop would flip vy twice and cancel out).
export function d3Case() {
  const speed = 710;
  const dt = 0.05;
  const state = {
    bricks: makeBricks(6),
    ball: { x: 80, y: 110, px: 80, py: 110, r: 7, vx: 0, vy: -speed },
  };
  state.ball.y += state.ball.vy * dt; // 74.5
  const b1 = brickAt(state, 4, 76); // row 1, col 0
  const b2 = brickAt(state, 84, 76); // row 1, col 1
  return { state, b1, b2, label: 'D3 seam double flip' };
}

edits.newText:
// --- D5: push-out — the ball is 15 px deep in the brick via its bottom face;
// after the bounce it must sit OUTSIDE the brick (y = brick.y + brick.h + r),
// not stay overlapping it (else it re-collides and re-flips next frame:
// "sticking").
export function d5Case() {
  const state = { bricks: makeBricks(1), ball: { x: 40, y: 60, px: 40, py: 60, r: 7, vx: 0, vy: -260 } };
  const brick = brickAt(state, 4, 48);
  return { state, brick, label: 'D5 push-out' };
}

